settings.custom_liquid:
{% assign clenzo_product_video = product.metafields.custom.floating_video.value %}

{% if clenzo_product_video != blank %}

<div id="clenzo-floating-video">

  <!-- =====================================================
       FLOATING VIDEO
       ===================================================== -->

  <div
    class="clenzo-video-floating"
    id="clenzoVideoFloating"
  >

    <!-- CLOSE -->
    <button
      type="button"
      class="clenzo-floating-close"
      id="clenzoFloatingClose"
      aria-label="Close video"
    >
      ×
    </button>

    <!-- DRAG AREA -->
    <div
      class="clenzo-floating-drag-area"
      id="clenzoFloatingDrag"
    >

      {{
        clenzo_product_video
        | video_tag:
          autoplay: true,
          loop: true,
          muted: true,
          controls: false,
          playsinline: true,
          preload: 'metadata',
          class: 'clenzo-floating-video'
      }}

      <!-- PLAY -->
      <button
        type="button"
        class="clenzo-floating-play"
        id="clenzoFloatingPlay"
        aria-label="Play video"
      >
        ▶
      </button>

      <!-- VIDEO LABEL -->
      <div class="clenzo-floating-label">
        Watch Video
      </div>

    </div>

  </div>


  <!-- =====================================================
       PRODUCT VIDEO POPUP
       ===================================================== -->

  <div
    class="clenzo-video-modal"
    id="clenzoVideoModal"
    aria-hidden="true"
  >

    <div
      class="clenzo-video-overlay"
      id="clenzoVideoOverlay"
    ></div>


    <div
      class="clenzo-video-popup"
      role="dialog"
      aria-modal="true"
    >

      <!-- CLOSE -->
      <button
        type="button"
        class="clenzo-popup-close"
        id="clenzoPopupClose"
        aria-label="Close"
      >
        ×
      </button>


      <!-- =================================================
           LEFT VIDEO
           ================================================= -->

      <div class="clenzo-popup-video">

        {{
          clenzo_product_video
          | video_tag:
            controls: false,
            autoplay: false,
            muted: true,
            loop: false,
            playsinline: true,
            preload: 'metadata',
            class: 'clenzo-popup-video-element'
        }}

        <!-- CUSTOM VIDEO CONTROLS -->

        <div class="clenzo-custom-controls">

          <button
            type="button"
            class="clenzo-control-button"
            id="clenzoPopupPlay"
            aria-label="Play / Pause"
          >
            ▶
          </button>

          <button
            type="button"
            class="clenzo-control-button"
            id="clenzoPopupMute"
            aria-label="Mute / Unmute"
          >
            🔊
          </button>

        </div>

      </div>


      <!-- =================================================
           RIGHT PRODUCT INFORMATION
           ================================================= -->

      <div class="clenzo-popup-product">

        {% if product.featured_image != blank %}

          <div class="clenzo-popup-product-image">

            <img
              src="{{ product.featured_image | image_url: width: 500 }}"
              alt="{{ product.featured_image.alt | default: product.title | escape }}"
              loading="lazy"
            >

          </div>

        {% endif %}


        <h2 class="clenzo-popup-title">
          {{ product.title }}
        </h2>


        <!-- PRICE -->

        <div class="clenzo-popup-price">

          {% assign clenzo_variant =
            product.selected_or_first_available_variant
          %}

          {% if clenzo_variant.compare_at_price
            and clenzo_variant.compare_at_price > clenzo_variant.price %}

            <span class="clenzo-sale-price">
              {{ clenzo_variant.price | money }}
            </span>

            <span class="clenzo-compare-price">
              {{ clenzo_variant.compare_at_price | money }}
            </span>

          {% else %}

            <span class="clenzo-sale-price">
              {{ clenzo_variant.price | money }}
            </span>

          {% endif %}

        </div>


        <!-- BUY NOW -->

        {% if clenzo_variant.available %}

          <button
            type="button"
            class="clenzo-buy-now"
            id="clenzoBuyNow"
            data-variant-id="{{ clenzo_variant.id }}"
          >
            BUY NOW
          </button>

        {% else %}

          <button
            type="button"
            class="clenzo-buy-now"
            disabled
          >
            SOLD OUT
          </button>

        {% endif %}


        <!-- VIEW PRODUCT -->

        <a
          href="{{ product.url }}"
          class="clenzo-view-product"
        >
          View Product
        </a>


        <!-- DESCRIPTION -->

        <div class="clenzo-description">

          <div class="clenzo-description-title">
            Description
          </div>

          <div class="clenzo-description-text">
            {{ product.description }}
          </div>

        </div>

      </div>

    </div>

  </div>

</div>


  <style>

    /* =====================================================
       MAIN
       ===================================================== */

    #clenzo-floating-video {
      position: relative;
      z-index: 9998;
    }


    /* =====================================================
       FLOATING VIDEO
       ===================================================== */

    #clenzo-floating-video
    .clenzo-video-floating {

      position: fixed;

      width: 220px;
      aspect-ratio: 9 / 16;

      right: 24px;
      bottom: 28px;

      background: #000;

      border-radius: 16px;

      overflow: visible;

      z-index: 9998;

      box-shadow:
        0 12px 35px rgba(0,0,0,.28);

      border: 2px solid rgba(255,255,255,.9);

      touch-action: none;

      user-select: none;

      transition:
        box-shadow .2s ease;
    }


    #clenzo-floating-video
    .clenzo-video-floating:hover {

      box-shadow:
        0 16px 42px rgba(0,0,0,.35);
    }


    /* =====================================================
       DRAG AREA
       ===================================================== */

    #clenzo-floating-video
    .clenzo-floating-drag-area {

      position: absolute;

      inset: 0;

      width: 100%;
      height: 100%;

      overflow: hidden;

      border-radius: 14px;

      cursor: grab;

      background: #000;
    }


    #clenzo-floating-video
    .clenzo-floating-drag-area:active {

      cursor: grabbing;
    }


    /* =====================================================
       FLOATING VIDEO
       ===================================================== */

    #clenzo-floating-video
    .clenzo-floating-video {

      width: 100%;
      height: 100%;

      display: block;

      object-fit: cover;

      object-position: center;

      margin: 0;

      pointer-events: none;

      user-select: none;

      -webkit-user-select: none;
    }
  /* =====================================================
       Floating Video Hover Effect
       ===================================================== */

/* Floating Video Hover Effect */
#clenzo-floating-video .clenzo-video-floating {
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

#clenzo-floating-video .clenzo-video-floating:hover {
  transform: scale(1.04);
  box-shadow:
    0 18px 45px rgba(0, 0, 0, 0.38);
  cursor: grab;
}

#clenzo-floating-video .clenzo-video-floating:active {
  cursor: grabbing;
}

    /* =====================================================
       CLOSE BUTTON
       ===================================================== */

    #clenzo-floating-video
    .clenzo-floating-close {

      position: absolute;

      top: -12px;
      right: -12px;

      width: 30px;
      height: 30px;

      display: flex;

      align-items: center;
      justify-content: center;

      border: 0;

      border-radius: 50%;

      background: #222;

      color: #fff;

      font-size: 22px;

      line-height: 1;

      font-weight: 400;

      cursor: pointer;

      z-index: 20;

      box-shadow:
        0 4px 14px rgba(0,0,0,.25);

      transition:
        transform .2s ease,
        background .2s ease;
    }


    #clenzo-floating-video
    .clenzo-floating-close:hover {

      background: #0B5ED7;

      transform: scale(1.08);
    }


    /* =====================================================
       FLOATING PLAY
       ===================================================== */

    #clenzo-floating-video
    .clenzo-floating-play {

      position: absolute;

      left: 50%;
      top: 50%;

      width: 35px;
      height: 35px;

      transform: translate(-50%, -50%);

      display: flex;

      align-items: center;
      justify-content: center;

      border: 0;

      border-radius: 50%;

      background: rgba(0,0,0,.38);

      color: rgba(255,255,255,.92);

      cursor: pointer;

      pointer-events: auto;

      z-index: 5;

      backdrop-filter: blur(1px);
    }


    /* =====================================================
       LABEL
       ===================================================== */

    #clenzo-floating-video
    .clenzo-floating-label {

      position: absolute;

      left: 10px;
      right: 10px;

      bottom: 9px;

      padding: 7px 8px;

      border-radius: 7px;

      background: rgba(0,0,0,.68);

      color: #fff;

      text-align: center;

      font-size: 11px;

      font-weight: 600;

      line-height: 1.2;

      pointer-events: none;

      backdrop-filter: blur(5px);
    }


    /* =====================================================
       MODAL
       ===================================================== */

    #clenzo-floating-video
    .clenzo-video-modal {

      position: fixed;

      inset: 0;

      width: 100%;
      height: 100%;

      display: flex;

      align-items: center;
      justify-content: center;

      padding: 20px;

      opacity: 0;

      visibility: hidden;

      pointer-events: none;

      z-index: 99999;

      transition:
        opacity .25s ease,
        visibility .25s ease;
    }


    #clenzo-floating-video
    .clenzo-video-modal.is-open {

      opacity: 1;

      visibility: visible;

      pointer-events: auto;
    }


    /* =====================================================
       OVERLAY
       ===================================================== */

    #clenzo-floating-video
    .clenzo-video-overlay {

      position: absolute;

      inset: 0;

      background: rgba(0,0,0,.78);
    }


    /* =====================================================
       POPUP
       ===================================================== */

    #clenzo-floating-video
    .clenzo-video-popup {

      position: relative;

      width: min(950px, 94vw);

      max-height: 90vh;

      display: grid;

      grid-template-columns:
        43% 57%;

      background: #fff;

      border-radius: 16px;

      overflow: hidden;

      z-index: 2;

      box-shadow:
        0 25px 80px rgba(0,0,0,.45);
    }


    /* =====================================================
       POPUP VIDEO
       ===================================================== */

    #clenzo-floating-video
    .clenzo-popup-video {

      position: relative;

      min-width: 0;

      background: #000;

      display: flex;

      align-items: center;
      justify-content: center;

      overflow: hidden;
    }


    #clenzo-floating-video
    .clenzo-popup-video-element {

      width: 100%;
      height: 100%;

      max-height: 90vh;

      display: block;

      object-fit: contain;

      background: #000;
    }


    /* =====================================================
       CUSTOM VIDEO CONTROLS
       ===================================================== */

    #clenzo-floating-video
    .clenzo-custom-controls {

      position: absolute;

      left: 15px;
      right: 15px;

      bottom: 15px;

      display: flex;

      gap: 8px;

      z-index: 10;
    }


    #clenzo-floating-video
    .clenzo-control-button {

      width: 38px;
      height: 38px;

      border: 0;

      border-radius: 50%;

      background: rgba(0,0,0,.65);

      color: #fff;

      cursor: pointer;

      font-size: 15px;

      backdrop-filter: blur(5px);
    }


    /* =====================================================
       POPUP CLOSE
       ===================================================== */

    #clenzo-floating-video
    .clenzo-popup-close {

      position: absolute;

      top: 10px;
      right: 10px;

      width: 40px;
      height: 40px;

      border: 0;

      border-radius: 50%;

      background: #fff;

      color: #111;

      font-size: 25px;

      line-height: 1;

      cursor: pointer;

      z-index: 30;

      box-shadow:
        0 4px 15px rgba(0,0,0,.25);
    }


    /* =====================================================
       PRODUCT AREA
       ===================================================== */

    #clenzo-floating-video
    .clenzo-popup-product {

      padding: 28px 28px 30px;

      max-height: 90vh;

      overflow-y: auto;

      background: #fff;
    }


    /* =====================================================
       PRODUCT IMAGE
       ===================================================== */

    #clenzo-floating-video
    .clenzo-popup-product-image {

      width: 100%;

      height: 180px;

      display: flex;

      align-items: center;
      justify-content: center;

      margin-bottom: 15px;
    }


    #clenzo-floating-video
    .clenzo-popup-product-image img {

      width: 100%;
      height: 100%;

      object-fit: contain;

      display: block;
    }


    /* =====================================================
       TITLE
       ===================================================== */

    #clenzo-floating-video
    .clenzo-popup-title {

      margin: 0 0 10px;

      font-size: 23px;

      line-height: 1.25;

      font-weight: 700;

      color: #111;
    }


    /* =====================================================
       PRICE
       ===================================================== */

    #clenzo-floating-video
    .clenzo-popup-price {

      display: flex;

      align-items: center;

      gap: 9px;

      margin-bottom: 18px;
    }


    #clenzo-floating-video
    .clenzo-sale-price {

      color: #d94336;

      font-size: 20px;

      font-weight: 700;
    }


    #clenzo-floating-video
    .clenzo-compare-price {

      color: #777;

      font-size: 14px;

      text-decoration: line-through;
    }


    /* =====================================================
       BUY NOW
       ===================================================== */

    #clenzo-floating-video
    .clenzo-buy-now {

      width: 100%;

      min-height: 50px;

      border: 0;

      border-radius: 8px;

      background: #0B5ED7;

      color: #fff;

      font-size: 15px;

      font-weight: 700;

      cursor: pointer;

      margin-bottom: 10px;
    }


    #clenzo-floating-video
    .clenzo-buy-now:hover {

      background: #084fae;
    }


    /* =====================================================
       VIEW PRODUCT
       ===================================================== */

    #clenzo-floating-video
    .clenzo-view-product {

      display: flex;

      align-items: center;
      justify-content: center;

      min-height: 44px;

      border: 1px solid #ddd;

      border-radius: 8px;

      color: #222;

      text-decoration: none;

      font-size: 14px;

      font-weight: 600;

      margin-bottom: 20px;
    }


    #clenzo-floating-video
    .clenzo-view-product:hover {

      color: #0B5ED7;

      border-color: #0B5ED7;
    }


    /* =====================================================
       DESCRIPTION
       ===================================================== */

    #clenzo-floating-video
    .clenzo-description {

      border-top: 1px solid #eee;

      padding-top: 15px;
    }


    #clenzo-floating-video
    .clenzo-description-title {

      font-size: 15px;

      font-weight: 700;

      margin-bottom: 9px;
    }


    #clenzo-floating-video
    .clenzo-description-text {

      color: #555;

      font-size: 14px;

      line-height: 1.6;
    }


    #clenzo-floating-video
    .clenzo-description-text p {

      margin: 0 0 12px;
    }


    /* =====================================================
       TABLET
       ===================================================== */

    @media screen and
      (min-width: 750px) and
      (max-width: 1199px) {

      #clenzo-floating-video
      .clenzo-video-floating {

        width: 135px;

        right: 18px;

        bottom: 20px;
      }

      #clenzo-floating-video
      .clenzo-video-popup {

        width: 94vw;

        grid-template-columns:
          45% 55%;
      }

    }


    /* =====================================================
       MOBILE
       ===================================================== */

    @media screen and
      (max-width: 749px) {

      #clenzo-floating-video
      .clenzo-video-floating {

        width: 150px;

        right: 14px;

        bottom: 82px;

        border-radius: 13px;
      }


      #clenzo-floating-video
      .clenzo-floating-close {

        width: 28px;
        height: 28px;

        top: -10px;
        right: -10px;

        font-size: 20px;
      }


      #clenzo-floating-video
      .clenzo-floating-play {

        width: 42px;
        height: 42px;
      }


      #clenzo-floating-video
      .clenzo-floating-play {

        font-size: 17px;
      }


      #clenzo-floating-video
      .clenzo-floating-label {

        font-size: 9px;

        left: 6px;
        right: 6px;

        bottom: 6px;

        padding: 6px 4px;
      }


      /* MOBILE POPUP */

      #clenzo-floating-video
      .clenzo-video-modal {

        padding: 8px;
      }


      #clenzo-floating-video
      .clenzo-video-popup {

        width: 96vw;

        max-height: 94vh;

        display: flex;

        flex-direction: column;

        border-radius: 13px;
      }


      #clenzo-floating-video
      .clenzo-popup-video {

        width: 100%;

        height: 52vh;

        min-height: 280px;

        max-height: 500px;
      }


      #clenzo-floating-video
      .clenzo-popup-product {

        max-height: 40vh;

        padding: 18px 16px 22px;
      }


      #clenzo-floating-video
      .clenzo-popup-product-image {

        height: 95px;
      }


      #clenzo-floating-video
      .clenzo-popup-title {

        font-size: 19px;
      }


      #clenzo-floating-video
      .clenzo-sale-price {

        font-size: 18px;
      }

    }


    /* =====================================================
       VERY SMALL MOBILE
       ===================================================== */

    @media screen and
      (max-width: 380px) {

      #clenzo-floating-video
      .clenzo-video-floating {

        width: 135px;

        bottom: 76px;
      }

    }


    body.clenzo-video-modal-open {

      overflow: hidden !important;
    }

  </style>


  <script>

    (function () {

      const floating =
        document.getElementById(
          'clenzoVideoFloating'
        );

      const dragArea =
        document.getElementById(
          'clenzoFloatingDrag'
        );

      const closeButton =
        document.getElementById(
          'clenzoFloatingClose'
        );

      const floatingPlay =
        document.getElementById(
          'clenzoFloatingPlay'
        );

      const modal =
        document.getElementById(
          'clenzoVideoModal'
        );

      const overlay =
        document.getElementById(
          'clenzoVideoOverlay'
        );

      const popupClose =
        document.getElementById(
          'clenzoPopupClose'
        );

      const popupPlay =
        document.getElementById(
          'clenzoPopupPlay'
        );

      const popupMute =
        document.getElementById(
          'clenzoPopupMute'
        );

      const floatingVideo =
        floating.querySelector(
          '.clenzo-floating-video'
        );

      const popupVideo =
        modal.querySelector(
          '.clenzo-popup-video-element'
        );

      const buyNow =
        document.getElementById(
          'clenzoBuyNow'
        );


      if (
        !floating ||
        !dragArea ||
        !modal ||
        !floatingVideo ||
        !popupVideo
      ) {
        return;
      }


      /* ===================================================
         FLOATING VIDEO AUTOPLAY
         =================================================== */

      /* ===================================================
         FLOATING VIDEO — ALWAYS MUTED ON PAGE LOAD
         =================================================== */

      floatingVideo.muted = true;
      floatingVideo.defaultMuted = true;
      floatingVideo.setAttribute('muted', '');
      floatingVideo.setAttribute('playsinline', '');
      floatingVideo.setAttribute('autoplay', '');
      floatingVideo.volume = 0;

      floatingVideo
        .play()
        .catch(function () {});


      /* ===================================================
         PLAY / PAUSE FLOATING VIDEO
         =================================================== */

      floatingPlay.addEventListener(
        'click',
        function (event) {

          event.stopPropagation();

          if (floatingVideo.paused) {

            floatingVideo
              .play()
              .catch(function () {});

            floatingPlay.textContent = '▶';

          } else {

            floatingVideo.pause();

            floatingPlay.textContent = 'Ⅱ';

          }

        }
      );


      /* ===================================================
         OPEN POPUP
         =================================================== */

      dragArea.addEventListener(
        'dblclick',
        function () {

          openPopup();

        }
      );


      /* Single click on video */

      let clickTimer = null;

      dragArea.addEventListener(
        'click',
        function (event) {

          if (
            event.target.closest(
              '#clenzoFloatingPlay'
            )
          ) {
            return;
          }

          clearTimeout(clickTimer);

          clickTimer = setTimeout(
            function () {

              openPopup();

            },
            80
          );

        }
      );


      function openPopup() {

        modal.classList.add(
          'is-open'
        );

        modal.setAttribute(
          'aria-hidden',
          'false'
        );

        document.body.classList.add(
          'clenzo-video-modal-open'
        );

        /* Stop floating video while popup is open */
        floatingVideo.pause();

        /* Start popup video from beginning with sound */
        popupVideo.pause();
        popupVideo.currentTime = 0;
        popupVideo.muted = false;
        popupVideo.defaultMuted = false;
        popupVideo.volume = 1;

        popupVideo
          .play()
          .catch(function () {});

      }


      /* ===================================================
         CLOSE POPUP
         =================================================== */

      function closePopup() {

        modal.classList.remove(
          'is-open'
        );

        modal.setAttribute(
          'aria-hidden',
          'true'
        );

        document.body.classList.remove(
          'clenzo-video-modal-open'
        );

        /* Stop popup video immediately */
        popupVideo.pause();
        popupVideo.currentTime = 0;
        popupVideo.muted = true;
        popupVideo.volume = 0;

        /* Keep floating video muted */
        floatingVideo.muted = true;
        floatingVideo.volume = 0;

      }


      popupClose.addEventListener(
        'click',
        closePopup
      );


      overlay.addEventListener(
        'click',
        closePopup
      );


      document.addEventListener(
        'keydown',
        function (event) {

          if (
            event.key === 'Escape' &&
            modal.classList.contains(
              'is-open'
            )
          ) {

            closePopup();

          }

        }
      );


      /* ===================================================
         PAGE VISIBILITY SAFETY
         =================================================== */

      document.addEventListener(
        'visibilitychange',
        function () {
          if (document.hidden) {
            floatingVideo.pause();
            popupVideo.pause();
          }
        }
      );


      /* ===================================================
         POPUP PLAY / PAUSE
         =================================================== */

      popupPlay.addEventListener(
        'click',
        function () {

          if (popupVideo.paused) {

            popupVideo
              .play()
              .catch(function () {});

            popupPlay.textContent = 'Ⅱ';

          } else {

            popupVideo.pause();

            popupPlay.textContent = '▶';

          }

        }
      );


      /* ===================================================
         POPUP MUTE
         =================================================== */

      popupMute.addEventListener(
        'click',
        function () {

          popupVideo.muted =
            !popupVideo.muted;

          popupMute.textContent =
            popupVideo.muted
              ? '🔇'
              : '🔊';

          if (!popupVideo.muted) {
            popupVideo.volume = 1;
          }

        }
      );


      /* ===================================================
         BUY NOW
         =================================================== */

      if (buyNow) {

        buyNow.addEventListener(
          'click',
          async function () {

            const variantId =
              buyNow.dataset.variantId;

            if (!variantId) return;

            buyNow.disabled = true;

            buyNow.textContent =
              'ADDING...';

            try {

              const response =
                await fetch(
                  '/cart/add.js',
                  {
                    method: 'POST',

                    headers: {
                      'Content-Type':
                        'application/json',
                      'Accept':
                        'application/json'
                    },

                    body: JSON.stringify({
                      items: [{
                        id:
                          Number(variantId),
                        quantity: 1
                      }]
                    })
                  }
                );


              if (!response.ok) {

                throw new Error(
                  'Could not add product'
                );

              }


              window.location.href =
                '/checkout';

            } catch (error) {

              buyNow.disabled = false;

              buyNow.textContent =
                'BUY NOW';

            }

          }
        );

      }


      /* ===================================================
         DRAG / TOUCH
         =================================================== */

      let dragging = false;

      let moved = false;

      let startX = 0;
      let startY = 0;

      let startRight = 0;
      let startBottom = 0;


      function pointerStart(event) {

        if (
          event.target.closest(
            '#clenzoFloatingPlay'
          )
        ) {
          return;
        }

        dragging = true;

        moved = false;

        const point =
          event.touches
            ? event.touches[0]
            : event;


        startX = point.clientX;
        startY = point.clientY;


        const rect =
          floating.getBoundingClientRect();


        startRight =
          window.innerWidth -
          rect.right;

        startBottom =
          window.innerHeight -
          rect.bottom;

        floating.style.left =
          rect.left + 'px';

        floating.style.top =
          rect.top + 'px';

        floating.style.right =
          'auto';

        floating.style.bottom =
          'auto';

      }


      function pointerMove(event) {

        if (!dragging) return;


        const point =
          event.touches
            ? event.touches[0]
            : event;


        const deltaX =
          point.clientX - startX;

        const deltaY =
          point.clientY - startY;


        if (
          Math.abs(deltaX) !== 0 ||
          Math.abs(deltaY) !== 0
        ) {

          moved = true;

        }


        const rect =
          floating.getBoundingClientRect();


        let newLeft =
          rect.left + deltaX;

        let newTop =
          rect.top + deltaY;


        const maxLeft =
          window.innerWidth -
          rect.width;

        const maxTop =
          window.innerHeight -
          rect.height;


        newLeft =
          Math.max(
            4,
            Math.min(
              newLeft,
              maxLeft - 4
            )
          );


        newTop =
          Math.max(
            4,
            Math.min(
              newTop,
              maxTop - 4
            )
          );


        floating.style.left =
          newLeft + 'px';

        floating.style.top =
          newTop + 'px';


        startX =
          point.clientX;

        startY =
          point.clientY;


        event.preventDefault();

      }


      function pointerEnd() {

        dragging = false;

      }


      dragArea.addEventListener(
        'mousedown',
        pointerStart
      );

      document.addEventListener(
        'mousemove',
        pointerMove
      );

      document.addEventListener(
        'mouseup',
        pointerEnd
      );


      dragArea.addEventListener(
        'touchstart',
        pointerStart,
        { passive: false }
      );

      document.addEventListener(
        'touchmove',
        pointerMove,
        { passive: false }
      );

      document.addEventListener(
        'touchend',
        pointerEnd
      );


      /* ===================================================
         CLOSE FLOATING VIDEO
         =================================================== */

      closeButton.addEventListener(
        'click',
        function (event) {

          event.stopPropagation();

          /* Hide floating window */
          floating.style.display = 'none';

          /* Stop and reset floating video */
          floatingVideo.pause();
          floatingVideo.currentTime = 0;

          /* Stop and reset popup video too */
          popupVideo.pause();
          popupVideo.currentTime = 0;
          popupVideo.muted = true;
          popupVideo.volume = 0;

          /* Close popup if it is open */
          modal.classList.remove('is-open');
          modal.setAttribute('aria-hidden', 'true');
          document.body.classList.remove('clenzo-video-modal-open');

        }
      );


      /* ===================================================
         DISABLE RIGHT CLICK ON VIDEO
         =================================================== */

      floatingVideo.addEventListener(
        'contextmenu',
        function (event) {

          event.preventDefault();

        }
      );


      popupVideo.addEventListener(
        'contextmenu',
        function (event) {

          event.preventDefault();

        }
      );

    })();

  </script>

{% endif %}
